export const SCOUTING: Record<Confidence, { game: string; plain: string; desc: string }> = {
  high: { game: "Verified", plain: "High confidence", desc: "We found lots of proof from many sources, and it all points the same way." },
  medium: { game: "Scouted", plain: "Medium confidence", desc: "We found good proof on at least two topics, but some parts are missing or mixed." },
  low: { game: "Rumored", plain: "Low confidence", desc: "We found only a little proof. It may be old, unclear or mostly talk." },
  insufficient: { game: "Unidentified", plain: "Not enough evidence", desc: "Not enough proof yet, so we leave this score blank." },
};

export const fullName = (m: Pick<RosterMember, "firstName" | "lastName">) => `${m.firstName} ${m.lastName}`;
export const monogram = (m: Pick<RosterMember, "firstName" | "lastName">) =>
  `${m.firstName[0] ?? ""}${m.lastName[0] ?? ""}`.toUpperCase();
export const rosterMember = (slug: string) => ROSTER.find((m) => m.slug === slug);
export const scoredCount = (m: RosterMember) => AXES.filter((a) => m.scores[a.key].score !== null).length;
export const REGIONS = [...new Set(ROSTER.map((m) => m.region))].sort();
export const TAGS = [...new Set(ROSTER.flatMap((m) => m.tags))].sort();
export const billUrl = (id: string) => {
  return `https://bills.juris.ph/bills/house/${id.toLowerCase()}`;
};
export const billPdfUrl = (id: string) => `https://docs.congress.hrep.online/legisdocs/basic_20/${id}.pdf`;
export const regionShort = (r: string) => {
  const m = r.match(/\(([^)]+)\)/);
  return m ? m[1]! : r;
};

/** Radar pole values come straight from the dataset; null when the axis is not scored. */
export const radarValues = (m: Member) =>
  AXES.flatMap((a) => {
    const scored = m.stats[a.key].score !== null;
    return [
      { axis: a, pole: "pos" as const, label: a.posRadar, value: scored ? (m.radar[a.posRadarKey] ?? null) : null },
      { axis: a, pole: "neg" as const, label: a.negRadar, value: scored ? (m.radar[a.negRadarKey] ?? null) : null },
    ];
  });

export const STATUS_TEXT: Record<Status, string> = {
  active: "Active",
  deceased: "Deceased",
  expelled: "Expelled from the House",
  changed_office: "Changed office",
};

export const fmtDate = (iso: string) =>
  new Date(iso + "T00:00:00Z").toLocaleDateString("en-PH", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });

export const BETTERGOV_URL = "https://bettergov.ph";

export const place = (m: Pick<RosterMember, "municipality" | "province">) =>
  [m.municipality, m.province].filter(Boolean).join(", ");

import jurisAuthors from "./juris-authors.json";
const JURIS = jurisAuthors as Record<string, { name: string; bills: number }>;
/** BatasWatch (bills.juris.ph) author page for a House member code, built by scripts/build-juris.py. */
export const jurisAuthorUrl = (houseCode?: string | null) => {
  const a = houseCode ? JURIS[houseCode] : undefined;
  return a ? `https://bills.juris.ph/authors?${new URLSearchParams({ author: a.name })}` : null;
};
